{id:"VT05-01",type:"SCHOOL CAMPAIGN POSTER + ONLINE ARTICLE",title:"BRING YOUR OWN BOTTLE",subtitle:"Refill. Reuse. Reduce.",poster:{headline:"BRING YOUR OWN BOTTLE",tagline:"Small habit, big difference.",audience:"All pupils and staff",date:"Green Week: 3–7 August",notice:"Refill stations are available beside the hall and canteen.",imageLabel:"REUSABLE BOTTLE",features:[["A","Refill","Top up your bottle at school"],["B","Reuse","Use the same bottle each day"],["C","Track","Classes record weekly progress"],["D","Learn","Find out how plastic waste affects the environment"]],footer:"Remember to wash your bottle daily."},article:{heading:"Why the campaign matters",paragraphs:["The campaign encourages pupils to reduce the number of single-use drink containers they use during the school day.","The class tracking activity is intended to help pupils notice their habits and make small changes.","Pupils may use any suitable reusable bottle; the campaign does not require a particular brand or design."]}},
{id:"VT05-02",type:"LIBRARY POSTER + SCHOOL WEBPAGE",title:"READ AROUND THE WORLD",subtitle:"Stories take you places.",poster:{headline:"READ AROUND THE WORLD",tagline:"Explore a new place through a book.",audience:"Primary 4–6 pupils",date:"Reading Month: 1–30 September",notice:"Collect a reading passport from the library.",imageLabel:"READING PASSPORT",features:[["A","Choose","Select a book from another country"],["B","Read","Complete one book"],["C","Reflect","Write one thing you learnt"],["D","Share","Recommend the book to a friend"]],footer:"Return your passport by 3 October."},article:{heading:"More than a reading challenge",paragraphs:["The programme aims to introduce pupils to stories and viewpoints from different places.","Pupils are encouraged to think about what they learn from each book rather than simply counting the number of pages they read.","Teachers may use selected recommendations for class discussions."]}},
{id:"VT05-03",type:"SPORTS NOTICE + ONLINE ARTICLE",title:"LUNCHTIME ACTIVE CLUB",subtitle:"Move safely. Have fun.",poster:{headline:"LUNCHTIME ACTIVE CLUB",tagline:"A short break can keep you moving.",audience:"Primary 5 and 6 pupils",date:"Every Tuesday and Thursday",time:"1.15–1.45 p.m.",venue:"Covered court",notice:"Wear sports shoes. Bring water.",imageLabel:"ACTIVE CLUB",features:[["A","Circuit","Short movement stations"],["B","Games","Simple team games"],["C","Stretch","Guided warm-up and cool-down"],["D","Track","Record personal goals"]],footer:"Join only if you have permission from your teacher."},article:{heading:"What makes the club different?",paragraphs:["The club is designed as a short activity rather than a competitive sports team.","Pupils can choose activities that match their ability and work towards personal goals.","The teacher leading the club will remind pupils about safe movement and hydration."]}},
{id:"VT05-04",type:"SCHOOL EVENT POSTER + ONLINE ARTICLE",title:"MAKER DAY",subtitle:"Build, test, improve.",poster:{headline:"MAKER DAY",tagline:"Turn an idea into something useful.",audience:"Primary 5–6 pupils",date:"14 November",time:"9.00 a.m.–12.00 noon",venue:"Innovation Room",price:"$8 per pupil",limit:"30 places",notice:"Work in pairs. Basic materials provided.",imageLabel:"MAKER DAY",features:[["A","Build","Create a working model"],["B","Test","Check whether it works"],["C","Improve","Change one part after testing"],["D","Share","Explain your final design"]],footer:"Bring a pencil and wear covered shoes."},article:{heading:"Learning through making",paragraphs:["Pupils will be given a simple design problem and asked to create a model in pairs.","Testing is an important part of the activity because pupils are expected to improve their first attempt.","The programme focuses on problem solving rather than producing identical models."]}},
{id:"VT05-05",type:"HEALTH POSTER + SCHOOL ARTICLE",title:"SLEEP WELL, LEARN WELL",subtitle:"Build a better bedtime routine.",poster:{headline:"SLEEP WELL, LEARN WELL",tagline:"Good habits start before bedtime.",audience:"Primary 4–6 pupils and families",date:"Wellness Week: 10–14 January",notice:"Try the five-night sleep routine challenge.",imageLabel:"SLEEP ROUTINE",features:[["A","Wind Down","Reduce exciting activities before bed"],["B","Screen Break","Put devices aside before bedtime"],["C","Routine","Keep a regular bedtime"],["D","Prepare","Pack your school bag earlier"]],footer:"Talk to an adult if you have concerns about sleep."},article:{heading:"Why routines can help",paragraphs:["A regular bedtime routine can make it easier for children to prepare for sleep.","The campaign does not suggest that every child needs exactly the same bedtime. Families can choose a suitable routine.","The five-night challenge is designed to help pupils notice which habits make bedtime calmer."]}},
{id:"VT05-06",type:"SCHOOL NOTICE + ONLINE ARTICLE",title:"SHARE THE PLAYGROUND",subtitle:"Everyone gets a turn.",poster:{headline:"SHARE THE PLAYGROUND",tagline:"Play fairly. Make space.",audience:"All pupils",date:"Playground Week: 5–9 May",notice:"Use the activity zones according to the timetable.",imageLabel:"PLAYGROUND",features:[["A","Rotate","Change activities when the bell rings"],["B","Share","Allow others to join"],["C","Care","Keep equipment in its place"],["D","Respect","Follow the playground rules"]],footer:"Speak to a teacher if there is a disagreement."},article:{heading:"Making playtime fair",paragraphs:["The school introduced activity zones so that different groups can enjoy the playground without overcrowding one area.","Pupils are expected to follow the timetable and share equipment.","The aim is to make playtime enjoyable while reducing disagreements about space."]}},
{id:"VT05-07",type:"MUSEUM POSTER + ONLINE GUIDE",title:"DISCOVER THE SCIENCE TRAIL",subtitle:"Look closer. Ask questions.",poster:{headline:"DISCOVER THE SCIENCE TRAIL",tagline:"Five stops. One big question.",audience:"Families and school groups",date:"Weekends in June",time:"10.00 a.m.–4.00 p.m.",venue:"Discovery Museum",price:"$6 per child",features:[["A","Energy","Test simple energy ideas"],["B","Light","Explore shadows and reflection"],["C","Sound","Investigate vibrations"],["D","Living Things","Observe models of habitats"]],footer:"Children must be accompanied by an adult."},article:{heading:"A trail for curious visitors",paragraphs:["Visitors move through four themed stations and complete a short observation task at each one.","The activities are designed to encourage questions rather than require visitors to memorise facts.","School groups may complete the trail together or move through the stations at their own pace."]}},
{id:"VT05-08",type:"SCHOOL FUNDRAISER POSTER + ONLINE ARTICLE",title:"BOOKS FOR ALL",subtitle:"Pass a good story on.",poster:{headline:"BOOKS FOR ALL",tagline:"Donate. Discover. Share.",audience:"All school families",date:"Collection: 6–17 July",notice:"Donate clean, gently used children's books.",imageLabel:"BOOK DRIVE",features:[["A","Donate","Bring suitable books to the library"],["B","Sort","Volunteers check each book"],["C","Share","Books go to community reading corners"],["D","Choose","Families may select a small number of donated books on Family Day"]],footer:"Please do not donate damaged or incomplete books."},article:{heading:"Where the books go",paragraphs:["Volunteers sort donated books before sending suitable ones to community reading corners.","The project aims to extend the life of books that are still useful.","Books that are damaged or incomplete cannot be accepted because they may not be safe or enjoyable to read."]}}
